  "「.DS_Store」「*.tmp」など、OS・ツールが自動生成した残骸ファイルを表示します": "Shows leftovers the OS or tools generated, such as .DS_Store and *.tmp",
  "「.DS_Store」「\\*.tmp」のような、OS やツールが勝手に作った残骸ファイルを表示するかどうかです。ふだんは隠しておき、掃除したいときだけオンにします。": "Whether to show leftovers the OS or tools created on their own, such as .DS_Store and *.tmp. Normally keep them hidden and turn this on only when tidying up.",
  "「{code} — {name}」を無効化します。新規の材種・素材作成で選択できなくなります（既存コードには影響しません）。": "\"{code} — {name}\" will be disabled and can no longer be chosen when creating material types or materials (existing codes are unaffected).",
  "「{code} — {name}」を有効化します。": "\"{code} — {name}\" will be enabled.",
