  "<span class=\"value-more\">検査数</span><span class=\"value-cell\"></span><span class=\"value-more\">合格数</span><span class=\"value-cell\"></span>": "<span class=\"value-more\">Inspected</span><span class=\"value-cell\"></span><span class=\"value-more\">Pass</span><span class=\"value-cell\"></span>",
  "> CKK 業務管理システムの公開ユーザーマニュアル。各ページの生 Markdown は URL 末尾に .md を付けて取得できます。": "> The public user manual for the CKK business management system. Raw Markdown for each page is available by appending .md to the URL.",
  "≤ 以下で最大（LD/割引）": "≤ and below, largest (LD / discount)",
  "≥ 以上で最小（径×長）": "≥ and above, smallest (dia. × length)",
  "● リンクを待っています…": "● Waiting to be linked…",
  "● 有効化を待っています…": "● Waiting to be enabled…",
  "⚠ 未選択 — この基準はどの工具種にも適用されません": "⚠ Nothing selected — this criterion applies to no tool type",
  "0 / {v0} 件": "0 / {v0}",
  "〇〇銀行": "Example Bank",
  "〇〇支店": "Example Branch",
  "0より大きい値": "A value greater than 0",
  "0より大きい倍率": "A multiplier greater than 0",
  "0以上": "0 or more",
  "1 つの指示書に割り当てる注文明細は同一製品である必要があります": "Order lines allocated to one work order must be for the same product",
  "1 つの指示書に割り当てる注文明細は同一製品にしてください": "Order lines allocated to one work order must be for the same product",
  "1 つの出荷書には同じ顧客の注文明細だけを載せられます": "A delivery order can only carry order lines from the same customer",
  "1 つの出荷書には同じ出荷先の注文明細だけを載せられます": "A delivery order can only carry order lines for the same ship-to",
  "1 つの出荷書には同じ配送方法（通常配送 / ユーザー直送）の注文明細だけを載せられます": "A delivery order can only carry order lines with the same delivery method (standard / direct to end user)",
  "1 つの明細を複数の指示書に分けて手配（分割）することも、同一製品の\n              複数明細を 1 つの指示書にまとめる（統合ロット）こともできます。\n              割当数は明細ごとの受注残が上限です": "You can split one line across several work orders, or bundle several lines of the same product into one (a combined lot). The allocation is capped by each line's remaining order quantity",
  "1 ユーザーに割当できるカードは 1 枚です。": "A user can hold only one card.",
  "1 画面に出す件数": "Items per screen",
  "1 回あたりの目安時間です。指示書を作るときの初期値になります。": "The rough time per run. It becomes the initial value when creating a work order.",
  "1 回あたりの有効時間（分）": "Valid time per use (min)",
  "1 回の応答に許す最大トークン数（Anthropic では必須）": "The maximum tokens allowed per response (required for Anthropic)",
  "1 件 20MB まで": "Up to 20MB each",
  "1 件の申請に複数の権限を混ぜられません（{ja}）": "One request cannot mix several permissions ({ja})",
  "1 件の操作の変更前後（before / after）まで開く": "Opens one operation down to its before/after payload.",
  "1 件の認証イベントの IP・端末シグネチャ・所有区分まで開く。従業員監視に隣接する情報": "Opens one auth event down to IP, device signature and ownership — adjacent to employee monitoring.",
  "1 人 1 回だけ回答できるようにする": "Allow only one response per person",
  "1 単位あたりの価格です。ここに入れた金額が、価格試算の材料費の参考価格として使われますので、実際の取引価格を入れてください。": "The price per unit. What you enter here becomes the reference price for the estimate's material cost, so use the real trade price.",
  "1 通に並べる件数の上限。超えた分は「ほか N 件」に畳まれます（畳まれた通知も送信済みとして扱われ、次の回には載りません）。": "The maximum listed in one email. Anything over is folded into \"and N more\" (folded notifications count as sent and do not reappear next time).",
  "1 通の件数": "Items per email",
  "1 本あたりの価格です。価格表の単価と違うときは、その場で差異として示されます。": "The price per piece. If it differs from the price list, the difference is flagged there and then.",
  "1 本あたりの加工時間です。加工費はこの時間から計算されるので、実際の段取りに近い値を入れてください。": "The machining time per piece. Machining cost is derived from it, so enter something close to the real setup.",
  "1 枚のカードで同時に開けるセッション数を変える。増やすと貸し借りが見えなくなる": "Changes how many sessions one card may hold at once; raising it hides card sharing.",
  "12時間（2:30 PM）": "12-hour (2:30 PM)",
  "1ヶ所": "1 place",
  "1ヶ所(R精度)": "1 place (R precision)",
  "1つの顧客×製品につき価格表は1件です。注文種別ごとの価格は下で追加します。": "There is one price list per customer × product. Add per-order-type prices below.",
  "1以上": "1 or more",
  "1以上を入力してください": "Enter 1 or more",
