  "いいえ": "No",
  "いずれか 1 名で通すか、全員の承認が必要かです。「いずれか1名」はグループの誰か 1 人が承認すれば次の段へ進みます。「全員」は承認依頼を出した時点のメンバー全員が承認するまで進みません。": "Whether one member suffices or everyone must approve. \"Any one member\" moves on as soon as someone in the group approves. \"All members\" waits until everyone who was a member when the request was made has approved.",
  "いずれか1名": "Any one member",
  "いつまでに図面が要るか": "When the drawing is needed by",
  "いつまでに図面が要るかです。空のままでも登録できますが、入れておくと一覧で並べ替えられ、期限を過ぎたものが色で分かります。": "When the drawing is needed by. You can leave it blank, but filling it in lets the list sort by it and colour overdue ones.",
  "いつまでに欲しいかの希望日です。確定した予定ではありません — 実際の入荷予定日は、発注書を作るときに仕入先と決めます。": "When you would like it by. It is not a firm date — the real expected receipt is agreed with the supplier when the purchase order is made.",
  "いつ戻すか": "When to restore",
  "いま復帰させる": "Restore now",
  "いま無効化すると管理者が居なくなり、権限を戻す画面が無いため psql でしか復旧できません。": "Disabling it now would leave no administrator, and with no screen to restore rights, only psql could recover it.",
  "インストールするとホーム画面 /\n                  デスクトップから起動でき、アプリとして通知を受け取れます（任意\n                  — ブラウザのままでも通知は届きます）。": "Installing it lets you launch from the home screen or desktop and receive notifications as an app (optional — notifications also arrive in the browser).",
