  "オープン（リンク待ち）で作成されます。テレビの画面に出るリンクコードを\n          「ディスプレイをリンク」で読み取ってリンクした後、この画面から\n          有効化できます（共有端末と同じ手順です）。": "It is created open (awaiting a link). Scan the link code shown on the TV via \"Link the display\", then enable it here (the same steps as a shared device).",
  "オープンな（未リンクの）プロファイルにのみリンクできます": "You can only link to an open (unlinked) profile",
  "オフにすると合格基準からの自動判定のみ（基準未設定の項目は常に手動）": "Turning it off leaves only automatic judgement from the criteria (items with no criteria stay manual)",
  "オフライン": "Offline",
