  "ここでの設定は各計算基準の「適用工具種」と同じデータです（計算基準\n        ページのチップと連動）。式の内容・順序は計算基準ページで編集します。": "What you set here is the same data as each criterion's applicable tool types (linked to the chips on the criteria page). Formulas and order are edited there.",
