  "このバージョンは指示書または検査記録で使用中のため変更できません。\n          内容を変更するには「新バージョンを作成」してください（既存の記録は\n          このバージョンのまま残ります）。": "This version cannot be changed while a work order or inspection record uses it. To change it, create a new version (existing records stay on this one).",
