  "このフォームは使い終わったものとして片付けられています。": "This form has been put away as finished with.",
  "このフォームは承認フローを使わない設定です。ここで段を作っても動きません\n          — 「編集」の基本設定で「承認フローを使う」を有効にしてください。": "This form is set not to use an approval flow. Steps created here do nothing — enable \"use an approval flow\" in the basic settings under Edit.",
  "このフォームを編集する権限がありません": "You do not have permission to edit this form",
  "このフォームを編集する権限がありません。": "You do not have permission to edit this form.",
