  "このプロファイルはまだリンクされていません": "This profile is not linked yet",
  "このプロファイルはまだ画面と結びついていません。ディスプレイの画面に\n          出ているリンクコードを、一覧の「リンク」から入力してください。": "This profile is not tied to a screen yet. Enter the link code shown on the display via Link in the list.",
  "このページに留まる": "Stay on this page",
  "このページを表示する権限がありません": "You do not have permission to view this page",
  "このページを離れると、入力した内容は保存されません。移動してもよろしいですか？": "Leaving this page discards what you entered. Leave anyway?",
  "このまま保存すると一部出荷になります。残りは後から別の出荷書で\n            出荷できます。": "Saving as it is makes this a partial shipment. The rest can go on a later delivery order.",
  "このユーザーには既に割当済のカードがあります": "This user already has a card assigned",
  "このユーザーには既に割当済のカードがあります。先に既存カードを取り消してください": "This user already has a card. Revoke the existing one first",
