  "この注文明細の指示書はまだありません": "There is no work order for this order line yet",
  "この注文明細の出荷書はまだありません": "There is no delivery order for this order line yet",
  "この注文明細は承認依頼中のためロックされています。承認が完了するまで編集できません。": "This order line is locked while approval is pending. It cannot be edited until approval finishes.",
  "この添付は削除できません（取込元の原本としてロックされています）": "This attachment cannot be deleted (it is locked as the imported original)",
