  "テーパー": "Taper",
  "できあがった製品をしまう場所です。保管場所マスタから選びます。決まっていなければ空のままでかまいません。": "Where the finished goods are stored. Chosen from the storage location master. Leaving it blank is fine.",
  "テスト": "Test",
  "テスト・サンプルの価格は有効終了日が必要です": "Test and sample prices need an end date",
  "テスト・サンプルは終了日が必須": "Test and sample entries need an end date",
  "テスト・サンプルは有効終了日が必須です": "Test and sample prices need an end date",
  "テスト工具種": "Test tool type",
  "テスト実行": "Test run",
  "デバイス": "Device",
  "デバイスオーナー": "Device owner",
  "テレビの画面に出ている QR を読み取るか、12 文字のリンクコードを\n          入力してください。共有端末と同じ形式です。": "Scan the QR shown on the TV, or type the 12-character link code. It is the same format as a shared device.",
  "テンプレート/CSV": "Template / CSV",
  "テンプレートの管理番号と名前です。指示書に紐づけるときにこの名前で選びます。": "The template's code and name. You pick it by this name when linking it to a work order.",
  "テンプレート情報": "Template information",
  "で行えます。": "is where you do it.",
  "で参照します。": "is where it is referenced.",
  "で申請し、別の人の承認を受けた期間だけ行えます。": "and can only be done for the period another person has approved.",
  "トークンを削除": "Delete the token",
  "トークンを貼り付け": "Paste the token",
  "ドキュメント": "Documents",
  "どの拠点のどのフロアの場所かです。在庫はこの場所の単位で置き場所が分かります。": "Which floor at which site. Stock locations are tracked at this granularity.",
  "どの拠点の作業場所かです。工程の実施場所を選ぶときは、その拠点の作業場所だけが候補に出ます。": "Which site the work location belongs to. Only that site's locations are offered for a step.",
  "どの拠点へ移すかです。移動元の在庫が減り、移動先の在庫が増えます。": "Which site to move it to. Stock falls at the source and rises at the destination.",
  "どの工程で使う検査表かです。指定しておくと、その工程の実行画面で選びやすくなります。": "Which step this sheet is for. Setting it makes it easier to pick on that step's execution screen.",
  "どの工程の並びを使うかです。製品ごとに登録された工程リストから選びます（在庫分の指示書では使いません）。": "Which step order to use. Chosen from the step lists registered per product (not used for from-stock work orders).",
  "どの受注に対する出荷かを注文請書で選びます。選ぶと、その注文請書の出荷できる明細が自動で入ります。": "Pick the order acceptance this ships against. Its shippable lines are filled in automatically.",
  "どの受注のための指示書かです。行を足せば同じ製品の複数の明細を 1 つの指示書（1 ロット）にまとめられ、逆に 1 つの明細を複数の指示書に分けて作ることもできます。在庫を積むためだけの指示書では空のままにできます。": "Which order the work order is for. Adding rows bundles several lines of the same product into one work order (one lot); conversely one line can be split across several work orders. For a stock-building work order, leave it blank.",
  "どの書類の何段目で使うかは「承認フロー」で決めます。": "Which document and which step it is used at is set under \"Approval flow\".",
  "どの製品の価格試算かです。製品にリンクしておくと、確定後に価格表の基準単価ソースとして選べるようになります。": "Which product the estimate is for. Linking it lets you choose it as a price list's base source once confirmed.",
  "ドラッグして並べ替え（スマホは長押し）": "Drag to reorder (press and hold on a phone)",
  "ドラッグで位置を、スライダーで大きさを調整します": "Drag to position it, use the slider for size",
  "トリガー": "Trigger",
  "トリガー（見積時 / 受注時）と参照元は作成後に変更できません。保存時に依頼番号 DSG-YYYYMM-NNNNN が採番されます。": "The trigger (at quote or at order) and the source cannot be changed after creation. A request number DSG-YYYYMM-NNNNN is assigned on save.",
  "トリガーが見積時のときに選びます。どの見積のための設計かを残しておくと、後から経緯をたどれます。": "Chosen when the trigger is at quote time. Recording which quote it is for makes the history traceable.",
  "トリガーが受注時のときに選びます。どの受注のための設計かを残します。": "Chosen when the trigger is at order time. It records which order the design is for.",
  "ドロップダウン（1つ選択）": "Dropdown (single)",
  "どんな業種の会社かです。最終需要家は大口のところだけ登録すれば十分で、すべての需要家を登録する必要はありません。": "What industry the company is in. Registering only major end users is enough; you need not register them all.",
  "どんな製品に使う種別かの補足です。": "A note on what products this type is for.",
  "なし": "None",
  "なし（記録しない）": "None (not recorded)",
  "なし（見積・受注に紐づけません）": "None (not tied to a quote or order)",
  "なし（単独起票）": "None (standalone)",
  "なぜキャンセルするか": "Why it is being cancelled",
  "なぜこの操作が必要かを書いてください。承認者はこれを読んで判断します": "Write why the operation is needed. The approver decides based on this",
  "なぜその素材が必要なのかを書きます。承認する人はここを見て判断しますので、「どの製品のどの工程で使うのか」まで書いておくと、やり取りが減ります。": "Write why the material is needed. The approver decides from this, so saying which product and which step it is for saves a round trip.",
  "なぜ描き直すか": "Why it is being redrawn",
