  "プロバイダ側の一時的な障害です": "A temporary fault on the provider's side",
  "プロファイルはオープン（リンク待ち）で作成されます。タブレットの\n            設定画面（/setup）に表示されるコードを「端末をリンク」で\n            入力またはスキャンしてリンクした後、この画面から有効化できます。": "The profile is created open (awaiting a link). Type or scan the code shown on the tablet's setup screen (/setup) via \"Link the device\", then enable it here.",
