  "改訂": "Revision",
  "改訂のときに、どの版を基に描き直すかです。空のままにすると、判定した時点のいちばん新しい版が使われます。依頼を出している間に別の改訂が先に完了した場合は、完了したときに履歴へその旨が残ります。": "For a revision, which version it is redrawn from. Left blank, the newest version at decision time is used. If another revision completes first while your request is open, that is noted in the history when it completes.",
  "改訂のときに、なぜ描き直すかを書きます。依頼内容とは別の欄です。あとから版の差分をたどるときの手がかりになります。": "For revisions, write why it is being redrawn. This is separate from the request details, and helps trace version differences later.",
