  "外すと、見積書や発注書などで新しく選べなくなります。すでにその会社で作った書類はそのまま残ります。": "Unchecking it stops them being chosen on new quotes and orders. Existing documents remain.",
  "外すと、材種や素材を登録するときの選択肢に出なくなります。使わなくなったメーカーや形状を、過去の登録は残したまま隠すときに使います。": "Unchecking it removes it from the choices when registering material types and materials. Use it to hide a manufacturer or shape you no longer use while keeping past records.",
