  "期間": "Period",
  "期間・数量条件を満たすルールが見積書作成時に自動適用されます（複数該当時は値引き額が最大のもの）。ルールは注文種別ごとに登録します。": "Rules meeting the period and quantity conditions apply automatically when quoting (the largest discount wins if several match). Rules are registered per order type.",
  "期間（開始日）": "Period (start date)",
  "期間（終了日）": "Period (end date)",
  "期間を設定するとテンポラリカードになり、期間外はログインできません\n            （終了日はその日いっぱい有効）。1 ユーザーに割当できるカードは 1\n            枚です。": "Setting a period makes it a temporary card that cannot log in outside it (the end date is valid all day). A user can hold only one card.",
  "期間外のカードはキオスクでログインできません（終了日はその日\n            いっぱい有効）。両方空欄で無期限に戻ります。ログイン中の\n            セッションは最長 8 時間で自然失効します。": "A card outside its period cannot log in on a shared device (the end date is valid all day). Blank both fields to return to no expiry. Active sessions expire naturally after at most 8 hours.",
  "期間限定": "Time-limited",
  "期間限定にする理由（任意）": "Reason for making it time-limited (optional)",
  "期間限定メンバーが承認できなくなる日時です。常任のメンバーには入りません。この日時を過ぎると自動で承認できなくなるので、手で消す必要はありません。": "When a time-limited member stops being able to approve. It does not apply to permanent members. They drop out automatically, so there is no need to remove them by hand.",
  "期間限定メンバーが承認できるようになる日時です。常任のメンバーには入りません。この日時より前は、承認者の候補に出てきません。": "When a time-limited member starts being able to approve. It does not apply to permanent members. Before it, they do not appear as an approver.",
  "期間限定メンバーは開始日時と終了日時の両方を入力してください": "A time-limited member needs both a start and an end time",
  "期間終了": "Period ends",
  "期間前": "Before the period",
  "期間内の仕入単価から参照価格を決める方法": "How the reference price is derived from purchase prices in the period",
  "期限つきで利用停止": "Suspend for a limited time",
  "期限なし": "No deadline",
  "期限は過ぎています。自動復帰は毎分の処理で行われるため、\n                  反映まで最大 1 分かかります。": "The deadline has passed. Automatic restoration runs each minute, so it can take up to a minute to take effect.",
  "期限切れ": "Expired",
