  "旧帳票（基本値・公差 Top/Bottom）—\n              入力すると合格範囲（下限/上限）を\n              目標値からの差分で自動計算します。直接入力する場合は空欄のままで\n              構いません。": "The legacy form (base value, tolerance top/bottom) — filling it in computes the pass range (lower/upper) automatically as offsets from the target. Leave it blank to enter the range directly.",
