  "実行依存はありません（先行工程なしで開始できます）": "There are no execution dependencies (it can start with no preceding step)",
  "実行順はカタログ既定順です（実際の実行可否は工程間依存の解決で決まります）。作業時間 (h) は任意 — 未入力は工程マスタの既定値。社内・外注可の工程は実施場所を選択できます。": "The order is the catalog default (what can actually run is decided by resolving inter-step dependencies). Work hours (h) are optional — blank uses the step master's default. Steps allowing outsourcing let you pick the execution location.",
  "実行中...": "Running…",
  "実際に受け取った拠点です。この拠点の在庫が増えますので、荷物が着いた場所を選んでください。": "The site that actually received it. Its stock increases, so choose where the goods arrived.",
  "実際に届いた数です。発注した数と違っても構いません — 分けて届く場合は、届いた分だけを記録します。": "How many actually arrived. It need not match the order — record only what came if it arrives in parts.",
  "実際の届け先（最終需要家）です。ユーザー直送を選んだときは必須で、通常配送でも記録として任意で選べます。": "The actual destination (end user). Required for direct-to-user delivery, and optional as a record for standard delivery.",
  "実施した作業を担当者・日付ごとに記録します（進行中のみ追加可）。共有端末からの実績には端末の既定作業場所が入ります。": "Records the work done per assignee and date (addable only while in progress). Actuals from a shared device carry that device's default work location.",
