  "受け取った注文書（PDF / PNG / JPG / WEBP、1 件 20MB\n            まで）をまとめて選ぶと、取込フォルダにそのまま置かれます。共有フォルダへ\n            直接コピーしたときと同じ経路で、順番に注文請書へ取り込まれます。": "Selecting the orders you received (PDF / PNG / JPG / WEBP, up to 20MB each) drops them straight into the intake folder. They are imported into order acceptances in turn, by the same route as copying into the shared folder.",
