  "書き出したファイル（.txt）に含まれるのは**フォームの作りだけ**です。\n          回答と共有設定は含まれないので、取り込んだフォームは非公開で始まります。\n          受付期間も設定し直してください。": "The exported file (.txt) contains **only the form's structure**. Responses and sharing settings are not included, so an imported form starts private. Set the open period again too.",
