  "書類から会社名を読み取れませんでした。書類を見て選択してください": "The company name could not be read from the document. Check it and choose",
  "書類ごとに、確定の前に通す承認の段を並べます。変更は今後の承認依頼から\n        適用され、進行中の書類は依頼した時点の設定のまま進みます。": "Lists the approval steps a document passes before it is confirmed. Changes apply from the next request; documents in flight keep their original settings.",
  "書類と見比べて、直すところがあれば「編集」で直してください": "Compare it with the document and use Edit to fix anything wrong",
  "書類なし": "No document",
  "書類に記載される出荷元の拠点です。在庫保管の出荷書では、この拠点に入庫されます。": "The origin site printed on the document. For stock-storage delivery orders, goods go into this site.",
  "書類の言語": "Document language",
  "書類の注文番号を読み取れませんでした": "The document's order number could not be read",
  "書類の内容（金額・種別など）で承認フローを分岐します。上から順に評価し、最初に一致したルールの段構成を既定フローの代わりに使います。どれにも一致しない書類は上の既定フローで進みます。変更は次の承認依頼から有効です。": "Branches the approval flow on the document's contents (amount, type…). Rules are evaluated top to bottom and the first match replaces the default flow. Anything matching nothing uses the default above. Changes take effect from the next request.",
