  "承認に失敗しました": "Could not approve",
  "承認に必要なのは、その書類を閲覧または編集できる権限です。書類を\n          開けないメンバーは、承認ボタンを押しても弾かれます。権限は\n          ユーザー管理 (SY01) のロールで決まります。": "Approving needs permission to view or edit the document. A member who cannot open it is rejected even after pressing approve. Permissions come from roles under Users (SY01).",
