  "図面をアップロード": "Upload a drawing",
  "図面をつくる製造の担当者です。承認されると、この人に「着手してください」の通知が届きます。承認されたあとでも「…」から変更できます。": "The production person who draws it. Once approved, they are told to make a start. You can still change it afterwards via \"…\".",
  "図面をつくる対象の製品です。必須です。この製品に過去の設計書があるかどうかで、新規か改訂かが自動で決まります。まだ登録が無い新規の製品でも、名称と単位だけあれば製品マスタに登録できるので、先に登録してから依頼してください。": "The product to be drawn. It is required. Whether the product has an earlier design document decides new versus revision automatically. Even a brand-new product can be registered in the product master with just a name and unit, so register it before raising the request.",
