  "誰が承認できるかは承認グループだけで決まります。加えて、承認を押すには\n        その書類を閲覧または編集できる権限が要ります。段のバッジは、今その段に\n        いるメンバーが書類を開けるかを表します。": "Who can approve is decided by the approval group alone. On top of that, pressing approve needs permission to view or edit the document. The step's badge shows whether its current members can open it.",
  "誰向けの価格試算かです。空のままでも計算できます — 相手が決まっていない段階の概算にも使えます。": "Who the estimate is for. You can leave it blank — it works for rough figures before a customer is decided.",
