  "単価（基準単価 × 数量倍率）と値引き（値引きルール）は顧客の価格表から自動計算されます。手入力はありません — 価格を変える場合は価格表側で設定してください。": "Unit price (base × quantity multiplier) and discounts (discount rules) are computed from the customer's price list. There is no manual entry — change prices on the price list.",
