  "端末アプリのアテステーション鍵を解除します。次回この端末のアプリが接続したときに新しい鍵が束縛されます（端末を交換・初期化した場合に使用）。": "Releases the device app's attestation key. A new key binds the next time the app connects (use it after replacing or wiping a device).",
