  "端末が指定されていません": "No device was given",
  "端末が持つ鍵の署名で確認済み（暗号的な証拠）。デバイストークンだけの場合は状況証拠どまり — 根拠は下の判定理由を参照。": "Verified by the signature of the device's own key (cryptographic proof). A device token alone is only circumstantial — see the reason below.",
