  "注文請書の取込（紙 → JSON）と、AI 補助タスクの両方がこの設定を使います。文字の読み取り（OCR）は常に社内で実行され、外部へは送信しません。": "Both order acceptance intake (paper → JSON) and the AI helper tasks use this setting. Character recognition (OCR) always runs in-house and is never sent out.",
  "注文請書の配送方法": "Order acceptance delivery method",
  "注文請書の保存に失敗しました": "Could not save the order acceptance",
  "注文請書の明細を確認し、価格に差異がなければ確定してください。": "Check the order acknowledgement lines and confirm it if the prices match.",
