  "注文請書を検索して明細を追加": "Search order acceptances and add lines",
  "注文請書を選択してください": "Select an order acceptance",
  "注文請書を選択すると、その注文請書の出荷できる注文明細ごとにグループが追加され、未出荷数量（受注数 − 出荷済）を関連ロットへ自動割付した明細が生成されます（指示書番号順・現物在庫と自明細の取り分の範囲）。ロットは各注文明細に紐づく指示書から選択し、在庫数に対して検証されます。": "Choosing an order acceptance adds a group per shippable line and generates lines that allocate the unshipped quantity (ordered − shipped) across related lots automatically (in work order number order, within physical stock and that line's share). Lots are chosen from the work orders tied to each line and validated against stock.",
