  "直接調達（発注書を経由しない入荷）を登録します。登録と同時に入荷先拠点の素材在庫へ入庫されます。発注入荷は素材発注書の「入荷完了」から自動登録されます。": "Registers a direct purchase (a receipt with no purchase order). It enters the receiving site's material stock on registration. Receipts against orders are registered automatically when the purchase order is completed.",
  "直送のときの実際の届け先です。出荷書を選ぶと注文請書のエンドユーザーから既定が入ります。": "The actual destination for direct delivery. Choosing a delivery order prefills it from the order acceptance's end user.",
  "追加": "Add",
  "追加した工具種は価格試算フォームの工具種として選択できます。計算入力は\n            丸棒系（参照単価ベース）です。現在「全工具種」に適用中の計算基準は\n            新しい種にも適用されます（追加後に調整できます）。": "Tool types you add become selectable on the price estimate form. Their inputs follow the round-bar family (reference-price based). Criteria currently applied to all tool types also apply to the new one (adjustable afterwards).",
  "追加しました": "Added",
