  "通常": "Normal",
  "通常 … 受注元へ納品します。納品書を荷物に同梱します / ユーザー直送 … 最終需要家へ直接送ります。納品書は別送し、価格は載せないのが通常です。出荷書を選ぶと、注文請書の配送方法から既定が入ります": "Standard … delivered to the ordering customer, with the delivery note in the package / direct to end user … sent straight to them, with the note sent separately and usually no prices. Choosing a delivery order prefills this from the order acceptance.",
  "通常 か 急ぎ かです。希望納期が入っていればそちらが目安になるので、優先度は「納期は先だが先に手を付けてほしい」といったときに使います。": "Normal or high. A requested date already gives a guide, so priority is for cases like \"the date is far off, but start on it first\".",
  "通常・OH・円筒などの形状です。": "The shape — standard, OH, cylinder and so on.",
  "通常（青）": "Normal (blue)",
