  "通常配送": "Standard delivery",
  "通常配送 … 受注元（またはその出荷先）へ届けます / ユーザー直送 … エンドユーザーへ直接送ります。出荷書は同じ出荷先・配送方法の注文だけをまとめられます。": "Standard delivery … goes to the ordering customer (or their ship-to). Direct to end user … goes straight to them. A delivery order can only bundle orders with the same ship-to and method.",
